WITH e AS (SELECT * EXCEPT (npc_name), ifNull(npc_name, '') AS npc FROM npc_shops WHERE capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), it AS (SELECT id, any(name) AS name FROM item_names WHERE id IN (SELECT item_id FROM e) GROUP BY id), o AS (SELECT zone_id, npc, max(n) AS openings FROM (SELECT zone_id, npc, kind, item_id, sum(n) AS n FROM e GROUP BY zone_id, npc, kind, item_id) GROUP BY zone_id, npc), ps AS (SELECT e.zone_id AS zone_id, e.npc AS npc, [round(median(c.x), 1), round(median(c.y), 1), round(median(c.z), 1)] AS pos FROM (SELECT DISTINCT capture_id, zone_id, npc, npc_id FROM e) e JOIN (SELECT capture_id, entity_id, x, y, z FROM entity_changes WHERE x IS NOT NULL AND (capture_id, entity_id) IN (SELECT capture_id, npc_id FROM e)) c ON c.capture_id = e.capture_id AND c.entity_id = e.npc_id GROUP BY e.zone_id, e.npc) SELECT e.zone_id AS zone, any(z.name) AS zone_name, e.npc AS npc_name, arraySort(groupUniqArray(e.kind)) AS kinds, uniqExact(e.item_id) AS items, any(o.openings) AS openings, uniqExact(e.capture_id) AS captures, min(e.ts_ms) AS first, max(e.last_ts) AS last, argMax(e.capture_id, e.last_ts) AS last_capture, arraySort(arrayFilter(x -> x != '', groupUniqArray(ifNull(it.name, '')))) AS item_names, any(ps.pos) AS pos FROM e LEFT JOIN it ON it.id = e.item_id LEFT JOIN o ON o.zone_id = e.zone_id AND o.npc = e.npc LEFT JOIN ps ON ps.zone_id = e.zone_id AND ps.npc = e.npc LEFT JOIN (SELECT id, any(name) AS name FROM zone_names GROUP BY id) z ON z.id = e.zone_id GROUP BY e.zone_id, e.npc ORDER BY zone_name, npc_name
